mapper.select:
SELECT COUNT(*)
FROM LECTURE
WHERE LEC_ID = #{lecId}
  AND LMS_PRF_ID = #{professorLmsPrfId}

SELECT COUNT(*)
FROM LECTURE_ANNOUNCEMENT a
JOIN LECTURE l ON l.LEC_ID = a.LEC_ID
WHERE a.LEC_ANN_ID = #{noticeId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}


WHERE a.LEC_ID = #{lecId}
  AND l.LMS_PRF_ID = #{professorLmsPrfId}
ORDER BY a.LEC_ANN_REG_DATE DESC, a.LEC_ANN_ID DESC

mapper.update:
UPDATE LECTURE_ANNOUNCEMENT
SET LEC_ANN_TITLE   = #{title},
    LEC_ANN_CONTENT = #{content, jdbcType=CLOB}
WHERE LEC_ANN_ID = #{noticeId}

UPDATE LECTURE_ANNOUNCEMENT_ATTACHMENT
SET ATT_VAL_STATUS = 'DEL'
WHERE LEC_ANN_ATT_ID = #{attachmentId}
  AND LEC_ANN_ID = #{noticeId}
  AND ATT_VAL_STATUS = 'ACT'
